/* _vec(): look up a vector as an atom's little-endian bytes; returns met 3
*/
static c3_z
_vec(const c3_c* nam_c, c3_y* out_y, c3_z cap_z)
{
  for ( c3_z i_z = 0; i_z < sizeof(vec_u) / sizeof(vec_u[0]); i_z++ ) {
    if ( 0 == strcmp(nam_c, vec_u[i_z].nam_c) ) {
      const c3_c* hex_c = vec_u[i_z].hex_c + 2;
      c3_z        len_z = strlen(hex_c);

      memset(out_y, 0, cap_z);
      for ( c3_z j_z = 0; j_z < len_z; j_z++ ) {
        c3_c c = hex_c[len_z - 1 - j_z];
        c3_y v = ( c <= '9' ) ? c - '0' : c - 'a' + 10;
        u3_assert( j_z / 2 < cap_z );
        out_y[j_z / 2] |= v << (4 * (j_z & 1));
      }
      return mesa_met3_bytes((len_z + 1) / 2, out_y);
    }
  }
  u3_assert(!"no such vector");
}

/* _check(): compare [len_z] bytes of [hav_y] (as an atom) against a vector
*/
static void
_check(const c3_c* nam_c, c3_z len_z, const c3_y* hav_y)
{
  c3_y wan_y[256];
  c3_z wan_z = _vec(nam_c, wan_y, sizeof(wan_y));
  c3_z hav_z = mesa_met3_bytes(len_z, hav_y);

  if ( (wan_z != hav_z) || memcmp(wan_y, hav_y, wan_z) ) {
    fprintf(stderr, "crypto: %s mismatch\r\n", nam_c);
    ret_i = 1;
  }
}

static const c3_c* pat_c = "/a/x/1//flow/0/poke/for/~zod/1";

static void
_key(c3_y key_y[32])
{
  for ( c3_y i_y = 0; i_y < 32; i_y++ ) key_y[i_y] = i_y;
}

static void
_test_symmetric(void)
{
  c3_y key_y[32], roo_y[32], out_y[256];
  const c3_y* hel_y = (const c3_y*)"hello world";

  _key(key_y);

  mesa_blake3(11, hel_y, 32, roo_y);
  _check("blake3", 32, roo_y);

  mesa_blake3_keyed(key_y, 11, hel_y, 16, out_y);
  _check("keyed", 16, out_y);

  mesa_blake3_kdf("mesa-aead", 32, key_y, 64, out_y);
  _check("kdf", 64, out_y);

  memcpy(out_y, hel_y, 11);
  mesa_crypt(key_y, 7, (const c3_y*)"mesa iv", 11, out_y);
  _check("crypt", 11, out_y);

  {
    c3_y iv_y[4] = { 0xef, 0xbe, 0xad, 0xde };
    c3_y pln_y[64];
    c3_z len_z = mesa_encrypt(key_y, 4, iv_y, 11, hel_y, out_y);
    c3_ds res_ds;

    _check("encrypt", len_z, out_y);

    res_ds = mesa_decrypt(key_y, 4, iv_y, len_z, out_y, pln_y);
    if ( (11 != res_ds) || memcmp(pln_y, hel_y, 11) ) {
      fprintf(stderr, "crypto: decrypt roundtrip failed\r\n");
      ret_i = 1;
    }

    out_y[len_z - 1] = 0x2;
    if ( -1 != mesa_decrypt(key_y, 4, iv_y, len_z, out_y, pln_y) ) {
      fprintf(stderr, "crypto: decrypt accepted bad trailer\r\n");
      ret_i = 1;
    }
  }

  {
    c3_c pat_o[128];
    c3_z len_z = mesa_seal_path(key_y, pat_c, out_y);
    c3_ds res_ds;

    _check("seal", len_z, out_y);

    res_ds = mesa_open_path(key_y, len_z, out_y, pat_o, sizeof(pat_o));
    if ( (res_ds < 0) || strcmp(pat_o, pat_c) ) {
      fprintf(stderr, "crypto: open-path roundtrip failed\r\n");
      ret_i = 1;
    }

    out_y[20] ^= 1;
    if ( -1 != mesa_open_path(key_y, len_z, out_y, pat_o, sizeof(pat_o)) ) {
      fprintf(stderr, "crypto: open-path accepted forgery\r\n");
      ret_i = 1;
    }
  }

  {
    c3_y mac_y[16];
    mesa_mac_binding(key_y, pat_c, roo_y, mac_y);
    _check("mac", 16, mac_y);

    if ( c3n == mesa_verify_mac(key_y, mac_y, pat_c, roo_y) ) {
      fprintf(stderr, "crypto: verify-mac rejected\r\n");
      ret_i = 1;
    }
    mac_y[0] ^= 1;
    if ( c3y == mesa_verify_mac(key_y, mac_y, pat_c, roo_y) ) {
      fprintf(stderr, "crypto: verify-mac accepted forgery\r\n");
      ret_i = 1;
    }
  }
}

static void
_test_keys(void)
{
  c3_y      sed_a[64], sed_b[64], roo_y[32], sym_y[32], syn_y[32], sig_y[64];
  mesa_keys kea_u, keb_u;

  mesa_blake3_kdf("libmesa test a", 0, NULL, 64, sed_a);
  mesa_blake3_kdf("libmesa test b", 0, NULL, 64, sed_b);
  _check("bod-a", 64, sed_a);

  mesa_keys_from_seed(&kea_u, sed_a);
  mesa_keys_from_seed(&keb_u, sed_b);

  _check("sgn-pub-a", 32, kea_u.sgn_pub_y);
  _check("cry-pub-a", 32, kea_u.cry_pub_y);
  _check("cry-pub-b", 32, keb_u.cry_pub_y);

  mesa_symmetric_key(keb_u.cry_pub_y, &kea_u, sym_y);
  mesa_symmetric_key(kea_u.cry_pub_y, &keb_u, syn_y);
  _check("sym-ab", 32, sym_y);
  _check("sym-ba", 32, syn_y);

  mesa_blake3(11, (const c3_y*)"hello world", 32, roo_y);
  mesa_sign_binding(&kea_u, pat_c, roo_y, sig_y);
  _check("sig", 64, sig_y);

  if ( c3n == mesa_verify_binding(kea_u.sgn_pub_y, sig_y, pat_c, roo_y) ) {
    fprintf(stderr, "crypto: verify-sig rejected\r\n");
    ret_i = 1;
  }
  if ( c3y == mesa_verify_binding(keb_u.sgn_pub_y, sig_y, pat_c, roo_y) ) {
    fprintf(stderr, "crypto: verify-sig accepted wrong key\r\n");
    ret_i = 1;
  }

  //  ring and pass roundtrip
  //
  {
    c3_y      rin_y[65], pas_y[65], sgn_y[32], cry_y[32];
    mesa_keys kec_u;

    rin_y[0] = 'B';
    memcpy(rin_y + 1, sed_a, 64);
    u3_assert( c3y == mesa_keys_from_ring(&kec_u, 65, rin_y) );
    u3_assert( 0 == memcmp(&kec_u, &kea_u, sizeof(kea_u)) );

    mesa_keys_pass(&kea_u, pas_y);
    u3_assert( c3y == mesa_pass_parse(65, pas_y, sgn_y, cry_y) );
    u3_assert( 0 == memcmp(sgn_y, kea_u.sgn_pub_y, 32) );
    u3_assert( 0 == memcmp(cry_y, kea_u.cry_pub_y, 32) );
    u3_assert( c3n == mesa_keys_from_ring(&kec_u, 3, (const c3_y*)"C12") );
  }
}

int
main()
{
  _test_symmetric();
  _test_keys();

  if ( !ret_i ) {
    fprintf(stderr, "crypto: ok\r\n");
  }
  return ret_i;
}
